INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','1','ar','Roblox Gift Card — Robux code','بطاقة Roblox Gift Card الأصلية — Robux code. يتم تسليم الرمز الخاص بك تلقائيًا مباشرة بعد الدفع.\n\nRegion: Global. Platform: PC / Mobile.\n\nHow to redeem: اتبع التعليمات المرسلة مع طلبك. تواصل مع البائع من صفحة طلبك إذا حدث أي خطأ.','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','1','es','Roblox Gift Card — Robux code','Tarjeta Roblox Gift Card original — Robux code. Tu código se entrega automáticamente justo después del pago.\n\nRegion: Global. Platform: PC / Mobile.\n\nHow to redeem: sigue las instrucciones enviadas con tu pedido. Contacta al vendedor desde la página de tu pedido si algo sale mal.','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','1','fr','Roblox Gift Card — Robux code','Carte Roblox Gift Card authentique — Robux code. Votre code est livré automatiquement juste après le paiement.\n\nRegion: Global. Platform: PC / Mobile.\n\nHow to redeem: suivez les instructions envoyées avec votre commande. Contactez le vendeur depuis la page de votre commande si quelque chose ne va pas.','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','1','id','Roblox Gift Card — Robux code','Roblox Gift Card asli — Robux code. Kode Anda dikirim otomatis segera setelah pembayaran.\n\nRegion: Global. Platform: PC / Mobile.\n\nHow to redeem: ikuti instruksi yang dikirim bersama pesanan Anda. Hubungi penjual dari halaman pesanan Anda jika ada yang ভুল.','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','1','ko','Roblox Gift Card — Robux code','정품 Roblox Gift Card — Robux code. 코드는 결제 직후 자동으로 전송됩니다.\n\nRegion: Global. Platform: PC / Mobile.\n\nHow to redeem: 주문과 함께 전송된 안내를 따르세요. 문제가 발생하면 주문 페이지에서 판매자에게 문의하세요.','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','1','ru','Roblox Gift Card — Robux code','Оригинальная Roblox Gift Card — Robux code. Ваш код доставляется автоматически сразу после оплаты.\n\nRegion: Global. Platform: PC / Mobile.\n\nHow to redeem: следуйте инструкциям, отправленным вместе с вашим заказом. Свяжитесь с продавцом на странице вашего заказа, если что-то пойдет не так.','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','1','zh','Roblox Gift Card — Robux code','正品 Roblox Gift Card — Robux code。您的代码会在付款后立即自动发送。\n\nRegion: Global. Platform: PC / Mobile.\n\nHow to redeem: 请按照随订单发送的说明操作。如果出现任何问题，请通过订单页面联系卖家。','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','10','ar','توصيل Robux سريع إلى حسابك — فوري','توصيل Robux سريع وأصلي إلى حسابك. يُكمل البائع عملية التسليم يدويًا، عادةً خلال 15 دقيقة.\n\nالمنطقة: Global. المنصة: PC / Mobile.\n\nطريقة الاسترداد: اتبع التعليمات المرسلة مع طلبك. تواصل مع البائع من صفحة طلبك إذا حدث أي خطأ.','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','10','es','Entrega rápida de Robux a tu cuenta — Instantánea','Entrega rápida y auténtica de Robux a tu cuenta. El vendedor completa la entrega manualmente, normalmente en 15 minutos.\n\nRegión: Global. Plataforma: PC / Mobile.\n\nCómo canjear: sigue las instrucciones enviadas con tu pedido. Contacta al vendedor desde la página de tu pedido si algo sale mal.','2026-10-16 05:23:06');
INSERT INTO `content_translations` (`entity_type`, `entity_id`, `locale`, `title`, `description`, `updated_at`) VALUES ('offer','10','fr','Livraison rapide de Robux sur votre compte — Instantanée','Livraison rapide et authentique de Robux sur votre compte. Le vendeur effectue la livraison manuellement, généralement sous 15 minutes.\n\nRégion : Global. Plateforme : PC / Mobile.\n\nComment utiliser : suivez les instructions envoyées avec votre commande. Contactez le vendeur depuis la page de votre commande en cas de problème.','2026-10-16 05:23:06');
